module tb;
  import reflib_pkg::*;
  import pkt_pkg::*;

  // Installs the registration hook generated by sv-weave.
  sv_weave_init_m u_init();

  initial begin
    packet p;
    p = ref_factory #(packet)::create();
    p.addr = 8'h10;
    p.data = 32'hcafe;
    $display("impl: %s", p.ref_impl_name());
    $display("%s", p.sprint());
    $finish;
  end
endmodule
